import { useQuery } from "@tanstack/react-query";
import { z } from "zod/mini";

const noticesSchema = z.array(
  z.object({
    license: z.string(),
    text: z.string(),
    packages: z.array(z.string()),
  })
);

type LicenseNotice = z.infer<typeof noticesSchema>[number];

/** Generated by `mise licenses:generate`; loaded only on the licences page. */
async function loadNotices(): Promise<LicenseNotice[]> {
  const { default: json } = await import("@/pages/about/model/third-party-licenses.gen.json?raw");
  return noticesSchema.parse(JSON.parse(json));
}

export function useThirdPartyLicenses() {
  return useQuery({
    queryKey: ["third-party-licenses"],
    queryFn: loadNotices,
    staleTime: Infinity,
  });
}
